async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);
  dessinerBilly(620, 500, 250);

  // le trésor
  fill(230, 190, 40);
  circle(460, 475, 50);

  if (mouseX > 400) {
    parler("Qui ose ?", 560, 230);
  } else {
    parler("Zzz", 560, 230);
  }

  dessinerRaoul(mouseX, mouseY, 60);
}

let jet = 0;

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);
  dessinerRaoul(250, 500, 120);
  dessinerBilly(600, 500, 250);

  if (jet !== 0) {
    parler("Jet : " + jet, 250, 280);
  }

  if (jet >= 12) {
    parler("Aïe !", 560, 230);
  }

  if (jet === 20) {
    parler("Coup critique", 250, 220);
  }
}

function mousePressed() {
  jet = lancerDe(20);
}

let pointsDeVie = 20;

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);
  dessinerBilly(600, 500, 250);

  if (pointsDeVie <= 0) {
    parler("Suivant !", 560, 230);
  } else {
    dessinerRaoul(250, 500, 120);
    parler("Vie : " + pointsDeVie, 250, 280);
  }
}

function mousePressed() {
  pointsDeVie = pointsDeVie - lancerDe(6);
}

section.markdown:
La porte du donjon demande la clé et une torche allumée. Les deux à la fois s'écrit `&&` :

```js
if (aLaCle && torcheAllumee) {
  porteOuverte = true;
}
```

Le dragon s'enfuit s'il est trop blessé, ou si le héros brandit la lance enchantée. L'un
des deux suffit, et ça s'écrit `||` :

```js
if (vieDuDragon < 20 || arme === "lance enchantée") {
  dragonEnFuite = true;
}
```

Avec `&&`, une seule réponse `false` suffit à fermer la porte. Avec `||`, une seule
réponse `true` suffit à faire fuir le dragon.

p5 fournit `mouseIsPressed`, un booléen qui vaut `true` tant que le bouton de la souris
reste enfoncé. La herse du château se lève quand Raoul est devant la porte et que le
bouton est enfoncé :

section.sketch:
async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);

  if (sontProches(mouseX, 500, 400, 500, 60) && mouseIsPressed) {
    dessinerChateauOuvert(400, 500, 360);
  } else {
    dessinerChateau(400, 500, 360);
  }

  dessinerRaoul(mouseX, 500, 60);
}

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);
  dessinerBilly(620, 500, 250);

  if (mouseX > 400 || mouseIsPressed) {
    parler("Qui ose ?", 560, 230);
  } else {
    parler("Zzz", 560, 230);
  }

  dessinerRaoul(mouseX, mouseY, 60);
}

let herseLevee = false;

function setup() {
  createCanvas(800, 600);
}

function draw() {
  background(20);
  if (herseLevee) {
    dessinerChateauOuvert(400, 500, 360);
  } else {
    dessinerChateau(400, 500, 360);
  }
}

function mousePressed() {
  herseLevee = !herseLevee;
}
